import React,{useEffect,useState} from 'react';
import {progressionAPI} from '../services/api';
import {useAuth} from '../context/AuthContext';
export default function BattlePassPage(){const{updateBalance}=useAuth();const[data,setData]=useState(null);const[notice,setNotice]=useState('');const load=async()=>{try{const r=await progressionAPI.getOverview();setData(r.data)}catch(e){setNotice(e.response?.data?.detail||'Impossible de charger le pass.')}};useEffect(()=>{load()},[]);const claim=async level=>{try{const r=await progressionAPI.claimBattlePass(level);if(r.data.balance!=null)await updateBalance(r.data.balance);setNotice(`Récompense débloquée : ${r.data.reward.label}`);load()}catch(e){setNotice(e.response?.data?.detail||'Impossible de récupérer la récompense.')}};const doPrestige=async()=>{try{const r=await progressionAPI.prestige();setNotice(`Prestige ${r.data.prestige} débloqué.`);load()}catch(e){setNotice(e.response?.data?.detail||'Prestige indisponible.')}};if(!data)return <div className="container py-5"><div className="progression-loading">Chargement…</div></div>;return <div className="container pass-page"><section className="pass-hero"><div><span className="section-kicker">WELLCASE / SEASON {data.season}</span><h1>Le <em>Battle Pass.</em></h1><p>Gagne de l’XP, débloque des ouvertures et construis ton identité.</p></div><div className="pass-level"><span>NIVEAU</span><strong>{data.level}</strong><small>{data.xp.toLocaleString('fr-FR')} XP</small></div></section><div className="pass-track-head"><div><b>PROGRESSION</b><span>{data.xp.toLocaleString('fr-FR')} / 5 000 XP</span></div><div className="pass-progress"><i style={{width:`${Math.min(100,data.xp/5000*100)}%`}}/></div></div>{notice&&<div className="inline-notice">{notice}<button onClick={()=>setNotice('')}>×</button></div>}<div className="pass-grid">{data.battle_pass.map(r=><article key={r.level} className={`pass-reward ${r.unlocked?'unlocked':''} ${r.claimed?'claimed':''}`}><div className="pass-level-number">{r.level}</div><div className="pass-reward-icon">{r.type==='cash'?'€':r.type==='open3'?'×3':r.type==='open5'?'×5':'✦'}</div><span>NIVEAU {r.level}</span><h3>{r.label}</h3><small>{r.xp.toLocaleString('fr-FR')} XP</small><button disabled={!r.unlocked||r.claimed} onClick={()=>claim(r.level)}>{r.claimed?'RÉCUPÉRÉ':r.unlocked?'RÉCUPÉRER':'VERROUILLÉ'}</button></article>)}</div><section className="cosmetic-pass-panel"><div><span className="section-kicker">IDENTITÉ COSMÉTIQUE</span><h2>Ton profil change avec le Pass.</h2><p>Le niveau 4 débloque le nom violet, le niveau 7 le thème NEON, et le niveau 10 le nom doré + badge ELITE.</p></div><div className="cosmetic-preview" style={{color:data.cosmetics?.name_color||undefined}}>{data.cosmetics?.badge||'PLAYER'}<small>{data.cosmetics?.pass_complete?'PASS TERMINÉ':'EN PROGRESSION'}</small></div></section><section className="prestige-panel"><div><span className="section-kicker">PRESTIGE</span><h2>Recommence plus fort.</h2><p>À 5 000 XP, passe Prestige. Ton XP lifetime reste conservé et chaque Prestige donne <b>+5% d’XP</b>.</p></div><div className="prestige-action"><strong>PRESTIGE {data.prestige?.prestige||0}</strong><span>{data.prestige?.season_xp||0} / 5 000 XP</span>{data.prestige?.ready&&<button onClick={doPrestige}>PASSER PRESTIGE</button>}</div></section><section className="multi-open-info"><div className="multi-icon">×5</div><div><span className="section-kicker">BONUS PREMIUM</span><h2>Ouvertures ×3 et ×5</h2><p>Les tickets sont conservés sur ton compte et utilisables directement depuis les caisses.</p></div><div className="ticket-count"><b>×3</b><strong>{data.open3_tokens}</strong><b>×5</b><strong>{data.open5_tokens}</strong></div></section></div>}
